# Analyze for potential rectangles (4 corners)
def find_rectangle_corners(positions):
    """Find sets of 4 points that form rectangles"""
    rects = []
    corners = set(positions)

    # Look for pairs sharing row or column
    for i, (r1, c1) in enumerate(corners):
        for j, (r2, c2) in enumerate(corners[i+1:], i+1):
            # Check if they share row or column
            if r1 == r2 and abs(c1 - c2) > 1:
                # Horizontal pair - find vertical partners
                for r3, c3 in corners:
                    for r4, c4 in corners:
                        if (c1, r3) in corners and (c2, r4) in corners:
                            rects.append({(r1, c1), (r1, c2), (r2, c1), (r2, c2)})
    return rects

positions = [(0, 0), (0, 2), (4, 1), (4, 3), (6, 1), (6, 3), (8, 1), (8, 3),
            (11, 0), (11, 2), (12, 1), (12, 3), (14, 2), (14, 4), (14, 6),
            (15, 1), (15, 3), (20, 1), (20, 3), (20, 5), (21, 2), (21, 4),
            (24, 3), (24, 5), (25, 0), (25, 2)]

rects = find_rectangle_corners(positions)
print(f"Found {len(rects)} potential rectangles")
for i, rect in enumerate(sorted(rects)[:10]):
    print(f"Rect {i}: {sorted(list(rect))}")

# Cleaner approach: fill between 8s in same row and same column

rows, cols = 27, 9
output_grid = [[0]*cols for _ in range(rows)]

positions = [(0, 0), (0, 2), (4, 1), (4,3), (6, 1), (6, 3), (8, 1), (8, 3),
            (11, 0), (11, 2), (12, 1), (12, 3), (14, 2), (14, 4), (14, 6),
            (15, 1), (15, 3), (20, 1), (20, 3), (20, 5), (21, 2), (21, 4),
            (24, 3), (24, 5), (25, 0), (25, 2)]

for r, c in positions:
    output_grid[r][c] = 8  # Start with original 8s

# Fill horizontally between 8s in same row
for r in range(rows):
    cols_in_row = sorted([c for c in range(cols) if (r, c) in positions])
    for i in range(len(cols_in_row) - 1):
        start, end = cols_in_row[i], cols_in_row[i+1]
        for c in range(start + 1, end):
            output_grid[r][c] = 8

# Fill vertically between 8s in same column  
for c in range(cols):
    rows_in_col = sorted([r for r in range(rows) if (r, c) in positions])
    for i in range(len(rows_in_col) - 1):
        start, end = rows_in_col[i], rows_in_col[i+1]
        for r in range(start + 1, end):
            output_grid[r][c] = 8

print("Output grid:")
for row in output_grid:
    print(row)

# Alternative: only fill INTERIORS of rectangles that have all 4 corners
# Plus keep the corner positions

output_grid = [[0]*9 for _ in range(27)]
positions = [(0, 0), (0, 2), (4, 1), (4,3), (6, 1), (6, 3), (8, 1), (8, 3),
            (11, 0), (11, 2), (12, 1), (12, 3), (14, 2), (14, 4), (14, 6),
            (15, 1), (15, 3), (20, 1), (20, 3), (20, 5), (21, 2), (21, 4),
            (24, 3), (24, 5), (25, 0), (25, 2)]

for r, c in positions:
    output_grid[r][c] = 8

rectangles = set()
for r1 in range(27):
    for r2 in range(r1 + 2, 27):
        for c1 in range(9):
            for c2 in range(c1 + 2, 9):
                p1 = (r1, c1)
                p2 = (r1, c2)
                p3 = (r2, c1)
                p4 = (r2, c2)
                if p1 in positions and p2 in positions and p3 in positions and p4 in positions:
                    rectangles.add((min(r1,r2), max(r1,r2), min(c1,c2), max(c1,c2)))

print(f"Found {len(rectangles)} rectangles")

# Fill interior of each rectangle
for (r1, r2, c1, c2) in sorted(rectangles):
    for r in range(r1 + 1, r2):
        for c in range(c1 + 1, c2):
            output_grid[r][c] = 8

print("\nOutput:")
for row in output_grid:
    print(row)

